    this.maxAttempts = defaultMaxAttempts,
    Future<void> Function(Duration duration)? sleep,
  })  : _dio = dio,
        policy = policy ??
            SyncRetryPolicy(
              maxAttempts: maxAttempts,
              baseDelayMs: 1000,
              maxDelayMs: 60000,
              backoffMultiplier: 2.0,
              jitterFactor: 0.3,
              random: Random(),
            ),
        _sleep = sleep ?? ((duration) => Future.delayed(duration));

