void budgetAndPassThroughTests() {
  group('GithubRateLimitRetryInterceptor budget & pass-through', () {
    test('persistent 429 exhausts the budget and surfaces the 429', () async {
      final f = _fixture(
        handler: (_) => _resp(429, '', {
