import 'dart:typed_data';
import 'package:dio/dio.dart';

class Stub implements HttpClientAdapter {
  final ResponseBody Function(RequestOptions) h;
  int calls = 0;
  Stub(this.h);
  @override
  Future<ResponseBody> fetch(RequestOptions options, Stream<Uint8List>? s, Future<void>? f) async {
    calls++;
    return h(options);
  }
  @override
  void close({bool force = false}) {}
}

ResponseBody resp(String body, int status, Map<String, List<String>> headers) =>
    ResponseBody.fromString(body, status, headers: headers);

void main() async {
  // 1. 200 with application/json content-type, get<String>
  var adapter = Stub((o) => resp('{"login":"octo"}', 200, {'content-type': ['application/json; charset=utf-8']}));
  final dio = Dio()..httpClientAdapter = adapter;
  try {
    final r = await dio.get<String>('https://api.github.com/user');
    print('1. get<String> JSON content-type OK: data=${r.data.runtimeType}');
  } catch (e) {
    print('1. get<String> JSON content-type THREW: ${e.runtimeType}: $e');
  }

  // 2. Retry flow: 429 with retry-after, then 200 with application/json, interceptor replay fetch<String>
  var calls = 0;
  final adapter2 = Stub((o) {
    calls++;
    return calls == 1
        ? resp('', 429, {'retry-after': ['1']})
        : resp('{"login":"octo"}', 200, {'content-type': ['application/json; charset=utf-8']});
  });
  final dio2 = Dio()..httpClientAdapter = adapter2;
  dio2.interceptors.add(ReplayInterceptor(dio2));
  try {
    final r = await dio2.get<String>('https://api.github.com/user');
    print('2. replay JSON OK: data=${r.data.runtimeType}');
  } catch (e) {
    print('2. replay JSON THREW: ${e.runtimeType}: $e');
  }

  // 3. Same retry flow with Map-typed caller get<Map<String,dynamic>>
  var calls3 = 0;
  final adapter3 = Stub((o) {
    calls3++;
    return calls3 == 1
        ? resp('', 429, {'retry-after': ['1']})
        : resp('{"login":"octo"}', 200, {'content-type': ['application/json; charset=utf-8']});
  });
  final dio3 = Dio()..httpClientAdapter = adapter3;
  dio3.interceptors.add(ReplayInterceptor(dio3));
  try {
    final r = await dio3.get<Map<String, dynamic>>('https://api.github.com/user');
    print('3. get<Map> JSON OK: data=${r.data.runtimeType}');
  } catch (e) {
    print('3. get<Map> JSON THREW: ${e.runtimeType}: $e');
  }
}

class ReplayInterceptor extends Interceptor {
  final Dio dio;
  ReplayInterceptor(this.dio);
  @override
  Future<void> onError(DioException err, ErrorInterceptorHandler handler) async {
    if (err.response?.statusCode != 429) {
      handler.next(err);
      return;
    }
    await Future.delayed(const Duration(milliseconds: 10));
    try {
      handler.resolve(await dio.fetch<String>(err.requestOptions));
    } on DioException catch (e) {
      handler.next(e);
    }
  }
}

