import 'dart:typed_data';
import 'package:dio/dio.dart';

class Stub implements HttpClientAdapter {
  final ResponseBody Function(RequestOptions) h;
  Stub(this.h);
  @override
  Future<ResponseBody> fetch(RequestOptions options, Stream<Uint8List>? s, Future<void>? f) async => h(options);
  @override
  void close({bool force = false}) {}
}

void main() async {
  final adapter = Stub((o) => ResponseBody.fromString(
      '{"login":"octo"}', 200, headers: {'content-type': ['application/json; charset=utf-8']}));
  final dio = Dio()..httpClientAdapter = adapter;
  dio.interceptors.add(InterceptorsWrapper(
    onResponse: (r, h) {
      print('onResponse data type: ${r.data.runtimeType}');
      h.next(r);
    },
  ));
  final r = await dio.get<String>('https://api.github.com/user');
  print('final data type: ${r.data.runtimeType}, value: ${r.data}');
  print('isJsonMimeType(application/json; charset=utf-8) = '
      '${Transformer.isJsonMimeType('application/json; charset=utf-8')}');
}

