class ReplayInterceptor extends Interceptor {
  final Dio dio;
  ReplayInterceptor(this.dio);
  @override
  Future<void> onError(DioException err, ErrorInterceptorHandler handler) async {
    if (err.response?.statusCode != 429) {
      handler.next(err);
      return;
