      final f = _thenOk({
        'x-ratelimit-reset': [_resetSecondsFromNow(7200)]
      });

      final response = await f.dio.get<String>('https://api.github.com/user');

      expect(response.statusCode, 200);
      expect(f.sleeps.single, const Duration(seconds: 3600));
    });

