      final f = _thenOk({
        'retry-after': ['10'],
        'x-ratelimit-reset': [_resetSecondsFromNow(600)],
      });

      await f.dio.get<String>('https://api.github.com/user');

      expect(f.sleeps.single, const Duration(seconds: 10));
    });
  });
}

