      dio: clientDio,
      policy: SyncRetryPolicy(
        maxAttempts: GithubRateLimitRetryInterceptor.defaultMaxAttempts,
        baseDelayMs: 1000,
        maxDelayMs: 60000,
        backoffMultiplier: 2.0,
        jitterFactor: 0.3,
        rateLimitMaxWaitSeconds: _rateLimitMaxWaitSeconds(reader),
        random: Random(),
