import 'package:dio/dio.dart';
import 'package:dmtools/dmtools.dart';

class Stub implements HttpClientAdapter {
  final ResponseBody Function(RequestOptions) h;
  int calls = 0;
  Stub(this.h);
  @override
  Future<ResponseBody> fetch(RequestOptions options, Stream<Uint8List>? s, Future<void>? f) async {
    calls++;
    return h(options);
  }
  @override
  void close({bool force = false}) {}
}

void main() async {
  PropertyReader.setOverrides({'SOURCE_GITHUB_TOKEN': 't'});
  var calls = 0;
  final adapter = Stub((o) {
    calls++;
    return calls == 1
        ? ResponseBody.fromString('', 429, headers: {'retry-after': ['1']})
        : ResponseBody.fromString('{"login":"octo"}', 200,
            headers: {'content-type': ['application/json']});
  });
  final dio = Dio()..httpClientAdapter = adapter;
  final http = GithubHttpClient(PropertyReader(), dio: dio);

  // A) caller types the call as Map (same pattern as confluence_client_java_name_tools getUri<dynamic>)
  try {
    final r = await dio.get<Map<String, dynamic>>('https://api.github.com/user');
    print('A get<Map> OK: data=${r.data.runtimeType}');
  } catch (e) {
    print('A get<Map> THREW: ${e.runtimeType}: ${e.toString().substring(0, 120.clamp(0, e.toString().length))}');
  }

  // B) caller uses <dynamic> (confluence_client_transfer post<dynamic> pattern)
  var calls2 = 0;
  final adapter2 = Stub((o) {
    calls2++;
    return calls2 == 1
        ? ResponseBody.fromString('', 429, headers: {'retry-after': ['1']})
        : ResponseBody.fromString('{"login":"octo"}', 200,
            headers: {'content-type': ['application/json']});
  });
  final dio2 = Dio()..httpClientAdapter = adapter2;
  final http2 = GithubHttpClient(PropertyReader(), dio: dio2);
  try {
    final r = await dio2.get<dynamic>('https://api.github.com/user');
    print('B get<dynamic> OK: data=${r.data.runtimeType} value=${r.data}');
  } catch (e) {
    print('B get<dynamic> THREW: ${e.runtimeType}: $e');
  }
}

