  //
  // CTL            = <any US-ASCII control character
  //                  (octets 0 - 31) and DEL (127)>
  // separators     = "(" | ")" | "<" | ">" | "@"
  //                | "," | ";" | ":" | "\" | <">
  //                | "/" | "[" | "]" | "?" | "="
  //                | "{" | "}" | SP | HT
  // token          = [REDACTED:Sensitive Value] CHAR except CTLs or separators>
  const String validChars = r'                                '
