      r' ABCDEFGHIJKLMNOPQRSTUVWXYZ   ^_'
      r'`abcdefghijklmnopqrstuvwxyz | ~ ';
  for (final int codeUnit in token.codeUnits) {
    if (codeUnit >= validChars.length ||
        validChars.codeUnitAt(codeUnit) == 0x20) {
      return false;
    }
  }
  return true;
}

